// Undefined only while no round has reported; a round that reports none leaves the running total alone.
function addUsage(total: UsageMetadata | undefined, round: UsageMetadata | undefined): UsageMetadata | undefined {
  if (!round) return total;
  if (!total) return {...round};
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}

